package com.yeyamo_mobile.api.messaging_service.infrastructure.persistence;import java.time.Instant;import java.util.UUID;import org.springframework.data.cassandra.core.mapping.MapId;import org.springframework.data.cassandra.repository.CassandraRepository;import org.springframework.data.domain.*;public interface MessageRepository extends CassandraRepository<MessageEntity,MapId>{Slice<MessageEntity>findByConversationId(UUID conversationId,Pageable pageable);Slice<MessageEntity>findByConversationIdAndSentAtLessThan(UUID conversationId,Instant before,Pageable pageable);}
